import sys
sys.path.insert(0, ".")
from dataclasses import dataclass
from src.services.payments import refund_payment

@dataclass
class Payment:
    id: str
    status: str
    refundable_amount: float
    provider_payment_id: str

class Repo:
    def __init__(self, payment): self.payment = payment; self.in_tx = False; self.notified = []
    def get_payment(self, pid): return self.payment
    def transaction(self):
        class _Tx:
            def __enter__(self): self.repo.in_tx = True
            def __exit__(self, *a): pass
            def __init__(self, repo): self.repo = repo
        return _Tx(self)
    def create_refund(self, payment_id, amount, gateway_refund_id):
        assert self.in_tx, "refund must be created inside transaction"
        r = type("R", (), {"id": gateway_refund_id, "payment_id": payment_id, "amount": amount, "status": "refunded"})
        self.created = r
        return r
    def update_payment_status(self, pid, status): self.payment.status = status

class Gateway:
    def refund(self, provider_payment_id, amount):
        assert not hasattr(repo, "created") or repo.created is None, "gateway call must precede persistence"
        return type("G", (), {"id": "gw-1"})
class Notifier:
    def payment_refunded(self, refund): repo.notified.append(refund.id)

repo = Repo(Payment("p1", "settled", 100.0, "prov-1"))
res = refund_payment("p1", 30.0, repo, Gateway(), Notifier())
assert res.refund_id == "gw-1" and res.amount == 30.0 and repo.payment.status == "refunded"
assert repo.notified == ["gw-1"], "side effect must fire after transaction"
try:
    refund_payment("p1", 30.0, repo, Gateway(), Notifier())
    raise AssertionError("second refund must fail: payment already refunded")
except ValueError as e:
    print("rejects second refund:", e)
try:
    refund_payment("p1", -1, Repo(Payment("p1", "settled", 100.0, "prov-1")), Gateway(), Notifier())
except ValueError as e:
    print("rejects negative amount:", e)
print("smoke OK:", res)
EOF
